import Foundation
import XCTest
import WorldsModels
@testable import WorldsSpreadsheet

/// The fixture was generated by the real desktop engine (`src/spreadsheet/engine.ts`)
/// and is shared with the Android instrumentation test, so all three platforms
/// are held to the same 121 displayed values.
private func desktopFixture(file: StaticString = #filePath) throws -> [String: JSONValue] {
    let url = URL(fileURLWithPath: "\(file)")
        .deletingLastPathComponent() // WorldsSpreadsheetTests
        .deletingLastPathComponent() // Tests
        .deletingLastPathComponent() // WorldsCore
        .deletingLastPathComponent() // Apple
        .deletingLastPathComponent() // repository
        .appendingPathComponent("Android/core/content/src/androidTest/assets/spreadsheet-desktop.json")
    let value = try JSONDecoder().decode(JSONValue.self, from: Data(contentsOf: url))
    guard case .object(let object) = value else { throw CocoaError(.fileReadCorruptFile) }
    return object
}

private func workbook(_ sheets: [[String: JSONValue]], active: String? = nil) -> SpreadsheetWorkbook {
    var sheet: [String: JSONValue] = ["sheets": .array(sheets.map { .object($0) })]
    if let active { sheet["activeSheetId"] = .string(active) }
    return SpreadsheetWorkbook(metadata: .object(["sheet": .object(sheet)]))
}

private func sheet(_ id: String, _ name: String, _ cells: [String: String]) -> [String: JSONValue] {
    ["id": .string(id), "name": .string(name), "cells": .object(cells.mapValues { .object(["v": .string($0)]) })]
}

private func evaluate(_ cells: [String: String]) -> [String: SpreadsheetCellResult] {
    SpreadsheetEngine.evaluate(workbook([sheet("s1", "Sheet 1", cells)]))["s1"]
}

final class SpreadsheetEngineTests: XCTestCase {
    func testEveryFormulaMatchesTheDesktopEngine() throws {
        let fixture = try desktopFixture()
        guard let stored = fixture["workbook"], case .object(let expected)? = fixture["expected"] else { return XCTFail("fixture shape") }
        let book = SpreadsheetWorkbook(metadata: .object(["sheet": stored]))
        let evaluation = SpreadsheetEngine.evaluate(book)
        var mismatches: [String] = []
        var checked = 0
        for (sheetID, cells) in expected {
            guard case .object(let wanted) = cells else { continue }
            for (key, value) in wanted {
                guard case .string(let display) = value else { continue }
                checked += 1
                let got = evaluation[sheetID][key]?.display
                if got != display { mismatches.append("\(sheetID)!\(key) expected <\(display)> got <\(got ?? "nil")>") }
            }
        }
        XCTAssertEqual(checked, 121)
        XCTAssertTrue(mismatches.isEmpty, mismatches.sorted().joined(separator: "\n"))
    }

    // Ported from src/spreadsheet/engine.test.ts.

    func testConvertsColumnIndicesAndNames() {
        XCTAssertEqual(SpreadsheetAddress.columnName(0), "A")
        XCTAssertEqual(SpreadsheetAddress.columnName(25), "Z")
        XCTAssertEqual(SpreadsheetAddress.columnName(26), "AA")
        XCTAssertEqual(SpreadsheetAddress.columnName(51), "AZ")
        XCTAssertEqual(SpreadsheetAddress.columnIndex("A"), 0)
        XCTAssertEqual(SpreadsheetAddress.columnIndex("Z"), 25)
        XCTAssertEqual(SpreadsheetAddress.columnIndex("AA"), 26)
        XCTAssertEqual(SpreadsheetAddress.columnIndex("AZ"), 51)
    }

    func testEvaluatesMathConditionalLookupFinancialAndCrossSheetFormulas() {
        let sales = sheet("sales", "Sales", [
            "A1": "Item", "B1": "Price", "A2": "Laptop", "B2": "4500", "A3": "Monitor", "B3": "1200",
            "A4": "Keyboard", "B4": "300", "B5": "=SUM(B2:B4)", "B6": "=SUMIF(B2:B4, \">=1000\")",
            "B7": "=VLOOKUP(\"Monitor\", A2:B4, 2, FALSE)", "B8": "=XLOOKUP(\"Keyboard\", A2:A4, B2:B4, \"Missing\")",
            "B9": "=IF(B5>5000, \"Target Met\", \"Below\")", "B10": "=IFERROR(10/0, \"Safe\")",
        ])
        let summary = sheet("summary", "Summary", ["A1": "=Sales!B5 * 1.15"])
        let evaluation = SpreadsheetEngine.evaluate(workbook([sales, summary]))
        XCTAssertEqual(evaluation["sales"]["B5"]?.value, .number(6000))
        XCTAssertEqual(evaluation["sales"]["B6"]?.value, .number(5700))
        XCTAssertEqual(evaluation["sales"]["B7"]?.value, .number(1200))
        XCTAssertEqual(evaluation["sales"]["B8"]?.value, .number(300))
        XCTAssertEqual(evaluation["sales"]["B9"]?.value, .text("Target Met"))
        XCTAssertEqual(evaluation["sales"]["B10"]?.value, .text("Safe"))
        guard case .number(let total)? = evaluation["summary"]["A1"]?.value else { return XCTFail("cross sheet") }
        XCTAssertEqual(total, 6900, accuracy: 1e-5)
    }

    func testDetectsCircularReferences() {
        let cells = evaluate(["A1": "=B1 + 1", "B1": "=A1 + 1"])
        XCTAssertEqual(cells["A1"]?.error, "#CYCLE!")
        XCTAssertEqual(cells["B1"]?.error, "#CYCLE!")
        XCTAssertEqual(evaluate(["A1": "=A1"])["A1"]?.display, "#CYCLE!")
    }

    // Error values and operators.

    func testErrorValuesMatchTheDesktop() {
        let cells = evaluate([
            "A1": "=1/0", "A2": "=NOSUCH(1)", "A3": "=Missing!A1", "A4": "=1+", "A5": "=\"x\"+1",
            "A6": "=SQRT(-1)", "A7": "=MATCH(5, B1:B3)", "A8": "=A1+1", "A9": "=SUM(A1:A2)",
            "A10": "=#REF!", "A11": "=#N/A", "A12": "=IFNA(A1, 0)", "A13": "=IFERROR(A1, 0)",
            "A14": "=[1]", "A15": "=A1:", "A16": "=ROUND(1",
        ])
        XCTAssertEqual(cells["A1"]?.error, "#DIV/0!")
        XCTAssertEqual(cells["A2"]?.error, "#NAME?")
        XCTAssertEqual(cells["A3"]?.error, "#REF!")
        XCTAssertEqual(cells["A4"]?.error, "#VALUE!")
        XCTAssertEqual(cells["A5"]?.error, "#VALUE!")
        XCTAssertEqual(cells["A6"]?.error, "#NUM!")
        XCTAssertEqual(cells["A7"]?.error, "#N/A")
        XCTAssertEqual(cells["A8"]?.error, "#DIV/0!")
        XCTAssertEqual(cells["A9"]?.error, "#DIV/0!")
        XCTAssertEqual(cells["A10"]?.error, "#REF!")
        XCTAssertEqual(cells["A11"]?.error, "#N/A")
        XCTAssertEqual(cells["A12"]?.error, "#DIV/0!")
        XCTAssertEqual(cells["A13"]?.display, "0")
        XCTAssertEqual(cells["A14"]?.error, "#VALUE!")
        XCTAssertEqual(cells["A15"]?.error, "#REF!")
        XCTAssertEqual(cells["A16"]?.error, "#VALUE!")
    }

    func testOperatorsFollowTheDesktopPrecedence() {
        let cells = evaluate([
            "A1": "=1+2*3^2", "A2": "=-(2+3)%", "A3": "=\"a\"&\"b\"&1.5", "A4": "=1=1", "A5": "=\"a\"<>\"b\"",
            "A6": "=2^3^2", "A7": "=-2^2", "A8": "=\"B\">\"a\"", "A9": "=10%", "A10": "=1;", "A11": "=(1+2)*3",
            "A12": "=0.1+0.2", "A13": "=\"x\"&0.1+0.2",
        ])
        XCTAssertEqual(cells["A1"]?.display, "19")
        XCTAssertEqual(cells["A2"]?.display, "-0.05")
        XCTAssertEqual(cells["A3"]?.display, "ab1.5")
        XCTAssertEqual(cells["A4"]?.display, "TRUE")
        XCTAssertEqual(cells["A5"]?.display, "TRUE")
        XCTAssertEqual(cells["A6"]?.display, "64")
        XCTAssertEqual(cells["A7"]?.display, "4")
        XCTAssertEqual(cells["A8"]?.display, "TRUE")
        XCTAssertEqual(cells["A9"]?.display, "0.1")
        XCTAssertEqual(cells["A10"]?.error, "#VALUE!")
        XCTAssertEqual(cells["A11"]?.display, "9")
        XCTAssertEqual(cells["A12"]?.display, "0.3")
        XCTAssertEqual(cells["A13"]?.display, "x0.30000000000000004")
    }

    func testReferencesRangesAndSheetNames() {
        let first = sheet("one", "Data sheet", ["A1": "5", "A2": "7", "B1": "=$A$1+A$2"])
        let second = sheet("two", "بيانات", ["A1": "=SUM('Data sheet'!A1:A2)", "A2": "=بيانات!A1*2", "A3": "=one!A1", "A4": "=sum('data SHEET'!a1:a2)"])
        let evaluation = SpreadsheetEngine.evaluate(workbook([first, second]))
        XCTAssertEqual(evaluation["one"]["B1"]?.display, "12")
        XCTAssertEqual(evaluation["two"]["A1"]?.display, "12")
        XCTAssertEqual(evaluation["two"]["A2"]?.display, "24")
        XCTAssertEqual(evaluation["two"]["A3"]?.display, "5")
        XCTAssertEqual(evaluation["two"]["A4"]?.display, "12")
    }

    func testFunctionsBeyondTheFixture() {
        let cells = evaluate([
            "A1": "10", "A2": "20", "A3": "", "A4": "x", "A5": "TRUE",
            "B1": "=SUM(A1:A5)", "B2": "=COUNTIF(A1:A5,\">=10\")", "B3": "=COUNTIF(A1:A5,\"x\")", "B4": "=SUMIF(A1:A2,\"<>10\")",
            "B5": "=REPT(\"a\", Z1)", "B6": "=LEFT(\"hello\")", "B7": "=MID(\"hello\", 0, 2)", "B8": "=SUBSTITUTE(\"aaa\",\"a\",\"bb\")",
            "B9": "=TEXTJOIN(\", \", FALSE, A1:A2)", "B10": "=INDEX(A1:A2, 3)", "B11": "=CHOOSE(3, \"a\", \"b\")",
            "B12": "=DATE(2026, 14, 1)", "B13": "=DATE(2026, 3, 0)", "B14": "=DATEDIF(\"2024-01-01\", \"2026-01-01\", \"Y\")",
            "B15": "=MONTH(46000)", "B16": "=DAY(\"2026-02-30\")", "B17": "=LEN(\"مرحبا\")", "B18": "=UPPER(\"straße\")",
            "B19": "=ROUND(-2.5)", "B20": "=ROUND(2.5)", "B21": "=IF(FALSE, 1)", "B22": "=IF(TRUE, 1, 1/0)",
            "B23": "=AVERAGE(A3:A4)", "B24": "=PERCENTILE(A1:A2, 2)", "B25": "=PMT(0, 10, 1000)", "B26": "=LOG(8, 2)",
            "B27": "=XLOOKUP(\"q\", A1:A2, A1:A2, \"none\")", "B28": "=EXACT(\"a\", \"a\")", "B29": "=NOT(Z9)", "B30": "=ISBLANK()",
        ])
        XCTAssertEqual(cells["B1"]?.display, "30")
        // Text and booleans compare as text against ">=10", exactly like the desktop matcher.
        XCTAssertEqual(cells["B2"]?.display, "4")
        XCTAssertEqual(cells["B3"]?.display, "1")
        XCTAssertEqual(cells["B4"]?.display, "20")
        XCTAssertEqual(cells["B5"]?.display, "a")
        XCTAssertEqual(cells["B6"]?.display, "h")
        XCTAssertEqual(cells["B7"]?.display, "he")
        XCTAssertEqual(cells["B8"]?.display, "bbbbbb")
        XCTAssertEqual(cells["B9"]?.display, "10, 20")
        XCTAssertEqual(cells["B10"]?.error, "#REF!")
        XCTAssertEqual(cells["B11"]?.error, "#VALUE!")
        XCTAssertEqual(cells["B12"]?.display, "2027-02-01")
        XCTAssertEqual(cells["B13"]?.display, "2026-02-28")
        XCTAssertEqual(cells["B14"]?.display, "2")
        XCTAssertEqual(cells["B15"]?.display, "12")
        XCTAssertEqual(cells["B16"]?.error, "#VALUE!")
        XCTAssertEqual(cells["B17"]?.display, "5")
        XCTAssertEqual(cells["B18"]?.display, "STRASSE")
        XCTAssertEqual(cells["B19"]?.display, "-2")
        XCTAssertEqual(cells["B20"]?.display, "3")
        XCTAssertEqual(cells["B21"]?.display, "FALSE")
        XCTAssertEqual(cells["B22"]?.display, "1")
        XCTAssertEqual(cells["B23"]?.error, "#DIV/0!")
        XCTAssertEqual(cells["B24"]?.error, "#NUM!")
        XCTAssertEqual(cells["B25"]?.display, "-100")
        XCTAssertEqual(cells["B26"]?.display, "3")
        XCTAssertEqual(cells["B27"]?.display, "none")
        XCTAssertEqual(cells["B28"]?.display, "TRUE")
        XCTAssertEqual(cells["B29"]?.display, "TRUE")
        XCTAssertEqual(cells["B30"]?.display, "TRUE")
    }

    func testLongChainsAndLongCyclesDoNotExhaustTheStack() {
        var cells: [String: String] = ["A1": "1"]
        for row in 2...500 { cells["A\(row)"] = "=A\(row - 1)+1" }
        for row in 1...300 { cells["B\(row)"] = "=B\(row == 300 ? 1 : row + 1)" }
        let results = evaluate(cells)
        XCTAssertEqual(results["A500"]?.display, "500")
        XCTAssertEqual(results["A250"]?.display, "250")
        XCTAssertEqual(results["B1"]?.error, "#CYCLE!")
        XCTAssertEqual(results["B150"]?.error, "#CYCLE!")
        XCTAssertEqual(results["B300"]?.error, "#CYCLE!")
        let nested = "=" + String(repeating: "(", count: 200) + "1" + String(repeating: ")", count: 200)
        XCTAssertEqual(evaluate(["A1": nested])["A1"]?.error, "#ERROR!")
        let shallow = "=" + String(repeating: "(", count: 40) + "1" + String(repeating: ")", count: 40)
        XCTAssertEqual(evaluate(["A1": shallow])["A1"]?.display, "1")
    }

    func testRawInputParsing() {
        XCTAssertEqual(SpreadsheetEngine.parseRawScalar(""), .empty)
        XCTAssertEqual(SpreadsheetEngine.parseRawScalar(" true "), .bool(true))
        XCTAssertEqual(SpreadsheetEngine.parseRawScalar("-12.5"), .number(-12.5))
        XCTAssertEqual(SpreadsheetEngine.parseRawScalar("1,234,567.5"), .number(1_234_567.5))
        XCTAssertEqual(SpreadsheetEngine.parseRawScalar("1,23"), .text("1,23"))
        XCTAssertEqual(SpreadsheetEngine.parseRawScalar("12%"), .number(0.12))
        XCTAssertEqual(SpreadsheetEngine.parseRawScalar(" hi "), .text(" hi "))
        XCTAssertEqual(SpreadsheetEngine.parseRawScalar("1e3"), .text("1e3"))
        XCTAssertEqual(SpreadsheetEngine.parseRawScalar(".5"), .text(".5"))
    }

    func testJavaScriptNumberText() {
        XCTAssertEqual(JSNumbers.toString(0.1 + 0.2), "0.30000000000000004")
        XCTAssertEqual(JSNumbers.toString(1e21), "1e+21")
        XCTAssertEqual(JSNumbers.toString(123_456_789_012), "123456789012")
        XCTAssertEqual(JSNumbers.toString(1e-7), "1e-7")
        XCTAssertEqual(JSNumbers.toString(0.000001), "0.000001")
        XCTAssertEqual(JSNumbers.toString(-1.5), "-1.5")
        XCTAssertEqual(JSNumbers.toString(-0.0), "0")
        XCTAssertEqual(JSNumbers.toString(.infinity), "Infinity")
        XCTAssertEqual(JSNumbers.toString(1.5e300), "1.5e+300")
        XCTAssertEqual(JSNumbers.number(" 12 "), 12)
        XCTAssertEqual(JSNumbers.number("0x10"), 16)
        XCTAssertEqual(JSNumbers.number(""), 0)
        XCTAssertEqual(JSNumbers.number("5."), 5)
        XCTAssertEqual(JSNumbers.number("-.5"), -0.5)
        XCTAssertTrue(JSNumbers.number("1e").isNaN)
        XCTAssertTrue(JSNumbers.number("nan").isNaN)
        XCTAssertTrue(JSNumbers.number("1,000").isNaN)
    }

    func testNumberFormatsMatchTheDesktop() {
        func show(_ value: Double, _ format: String, _ decimals: Int = 2) -> String {
            var style = SpreadsheetCellStyle()
            style.format = format
            style.decimals = decimals
            return SpreadsheetEngine.format(.number(value), style: style)
        }
        XCTAssertEqual(show(1234.5, "integer"), "1,235")
        XCTAssertEqual(show(-2.5, "integer"), "-2")
        XCTAssertEqual(show(1234.5678, "number"), "1,234.57")
        XCTAssertEqual(show(0.125, "number"), "0.13")
        XCTAssertEqual(show(1.005, "number"), "1.01")
        XCTAssertEqual(show(999.995, "number"), "1,000.00")
        XCTAssertEqual(show(-1234.5, "currency_sar"), "-SAR 1,234.50")
        XCTAssertEqual(show(99, "currency_usd", 0), "$99")
        XCTAssertEqual(show(-5, "accounting"), "(5.00)")
        XCTAssertEqual(show(0, "accounting"), "\u{2014}")
        XCTAssertEqual(show(0.1234, "percent"), "12.34%")
        XCTAssertEqual(show(0.00125, "percent", 1), "0.1%")
        XCTAssertEqual(show(12345.678, "scientific"), "1.23e+4")
        XCTAssertEqual(show(0.00012, "scientific", 1), "1.2e-4")
        XCTAssertEqual(show(1234.56789, "auto"), "1,234.5679")
        XCTAssertEqual(show(1e21, "auto"), "1,000,000,000,000,000,000,000")
        XCTAssertEqual(show(0.5, "date"), "0.5")
        XCTAssertEqual(JSNumbers.toFixed(1.005, 2), "1.00")
        XCTAssertEqual(JSNumbers.toFixed(0.125, 2), "0.13")
        XCTAssertEqual(JSNumbers.toFixed(-0.001, 2), "-0.00")
        XCTAssertEqual(SpreadsheetEngine.format(.bool(false), style: nil), "FALSE")
        XCTAssertEqual(SpreadsheetEngine.format(.number(.nan), style: nil), "NaN")
    }
}
